func All() []Operation {
	result := make([]Operation, len(catalog))
	copy(result, catalog)
	for index := range result {
		result[index].SuccessStatuses = append([]int(nil), result[index].SuccessStatuses...)
		result[index].Security = make([][]string, len(result[index].Security))
		for alternative := range result[index].Security {
			result[index].Security[alternative] = append([]string(nil), catalog[index].Security[alternative]...)
		}
	}
	return result
}
